<?php
session_start();
require_once __DIR__ . '/includes/automatic-results-schema.php';
require_once __DIR__ . '/includes/results-provider.php';

$requestId=(int)($_GET['request_id'] ?? ($_SESSION['fc_automatic_results_request_id'] ?? 0));
if($requestId<=0){header('Location: automatic-results.php');exit;}
$st=$pdo->prepare("SELECT rr.*, v.serial_number, v.pin, p.name product_name, u.phone, u.email FROM result_requests rr LEFT JOIN vouchers v ON v.id=rr.voucher_id LEFT JOIN products p ON p.id=v.product_id LEFT JOIN users u ON u.id=rr.user_id WHERE rr.id=? LIMIT 1");
$st->execute([$requestId]);$request=$st->fetch();
if(!$request){http_response_code(404);exit('Result request not found.');}
function arh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$completed = ($request['status']==='completed' && !empty($request['result_payload']) && !empty($request['result_access_token']));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Automatic Result Processing - FastCheckerGH</title><link rel="stylesheet" href="css/style.css"></head><body><header class="site-header"><div class="container header-container"><a class="logo" href="index.php"><span style="color:#171923">Fast</span><span style="color:#ff6500">Checker</span><span style="color:#171923">GH</span></a></div></header><main class="results-page"><div class="results-container"><div class="results-header"><span class="section-label">AUTOMATIC RESULTS</span><h1><?php echo $completed?'Result Ready':'Processing Result'; ?></h1><p><?php echo $completed?'Your result has been retrieved and saved securely.':'Your payment and checker assignment are complete. FastCheckerGH is now processing the result.'; ?></p></div><div class="result-form-card"><div class="checker-main"><div class="checker-row"><span class="checker-label">Examination</span><strong><?php echo arh($request['result_type']); ?></strong></div><div class="checker-row"><span class="checker-label">Year</span><strong><?php echo arh($request['exam_year']); ?></strong></div><div class="checker-row"><span class="checker-label">Index</span><strong><?php echo arh($request['index_number']); ?></strong></div><div class="checker-row"><span class="checker-label">Checker</span><strong>Assigned automatically</strong></div></div><?php if($completed): ?><a class="results-button" href="result-view.php?token=<?php echo arh($request['result_access_token']); ?>" style="display:block;text-align:center;margin-top:18px">View My Result</a><?php elseif(fc_result_provider_configured() && fc_result_provider_mode()==='waec_api'): ?><div id="processor" class="status-card" style="margin-top:18px"><strong>Retrieving result…</strong><p id="processor-message" style="margin-top:8px">Connecting to the authorized WAEC result service.</p></div><?php else: ?><div class="status-card" style="margin-top:18px"><strong>Automatic result service needs authorization</strong><p style="margin-top:8px">FastCheckerGH is ready for direct result retrieval, but an authorized WAEC API/RVS endpoint and credentials are not configured yet.</p><a class="results-button" href="https://eresults.waecgh.org/" target="_blank" rel="noopener noreferrer" style="display:block;text-align:center;margin-top:15px">Open Official WAEC eResults</a></div><?php endif; ?></div></div></main><?php include __DIR__ . '/includes/footer.php'; ?><?php if(!$completed && fc_result_provider_configured() && fc_result_provider_mode()==='waec_api'): ?><script>
const requestId=<?php echo (int)$requestId;?>; const box=document.getElementById('processor-message');
fetch('api/process-automatic-result.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'request_id='+encodeURIComponent(requestId)})
.then(r=>r.json().then(j=>({ok:r.ok,data:j})))
.then(x=>{if(x.data.success){box.innerHTML='<a href="'+x.data.result_url+'" style="color:#ff6500;font-weight:800">Result retrieved successfully. Open your result.</a>'; }else{box.textContent=x.data.message||'The result could not be retrieved.';}})
.catch(()=>{box.textContent='The result service could not be reached. Please try again later.';});
</script><?php endif; ?></body></html>
